<?php $id=(int)($_GET['id']??0);$employee=foundation_employee($pdo,$id);if(!$employee){echo '<div class="alert error">Employee not found.</div>';return;}$q=$pdo->prepare("SELECT id FROM hr_media WHERE user_id=? AND purpose='profile' LIMIT 1");$q->execute([$id]);$photo=$q->fetchColumn();$tab=(string)($_GET['tab']??'overview');if(!in_array($tab,['overview','employment','documents'],true))$tab='overview';?>
<section class="card profile-banner"><?php if($photo):?><img class="avatar large photo" src="media.php?employee=<?=$id?>" alt=""><?php else:?><span class="avatar large"><?=h(substr($employee['first_name'],0,1).substr($employee['last_name'],0,1))?></span><?php endif;?><div class="grow"><h2><?=h($employee['name'])?></h2><p class="hint"><?=h(($employee['designation_name']?:'Designation not assigned').' · '.($employee['department_name']?:'Department not assigned'))?></p><p class="hint"><?=h($employee['employee_code']?:'Employee ID not assigned')?></p></div><?php fbadge($employee['employment_status'],$employee['employment_status']==='Active');if(can($pdo,$user,'employees.edit')):?><a class="button" href="?page=employee-edit&id=<?=$id?>">Edit employee</a><?php endif;?></section>
<nav class="tabs" aria-label="Employee profile"><?php foreach(['overview'=>'Overview','employment'=>'Employment','documents'=>'Documents'] as $t=>$label):if($t==='documents'&&!can($pdo,$user,'documents.view'))continue;?><a href="?page=employee-view&id=<?=$id?>&tab=<?=$t?>" <?=$tab===$t?'aria-current="page"':''?>><?=$label?></a><?php endforeach;?></nav>
<?php if($tab==='overview'||$tab==='employment'):
$fields=$tab==='overview'?['username'=>'Username','email'=>'Work email','personal_email'=>'Personal email','mobile'=>'Mobile number','alternate_phone'=>'Alternate phone','birth_date'=>'Date of birth','gender'=>'Gender','blood_group'=>'Blood group','current_address'=>'Current address','permanent_address'=>'Permanent address','city'=>'City','state'=>'State','country'=>'Country','pin_code'=>'Postal code','emergency_name'=>'Emergency contact','emergency_phone'=>'Emergency number','emergency_relationship'=>'Relationship']:['employee_code'=>'Employee ID','department_name'=>'Department','designation_name'=>'Designation','role_name'=>'Role','manager_name'=>'Reporting manager','joining_date'=>'Joining date','employment_type'=>'Employment type','employment_status'=>'Employment status','login_status'=>'Login access'];
if($tab==='employment'){$q=$pdo->prepare('SELECT name FROM users WHERE id=?');$q->execute([$employee['manager_id']]);$employee['manager_name']=$q->fetchColumn();$employee['login_status']=$employee['active']?'Enabled':'Disabled';}
?><section class="card"><dl class="details"><?php foreach($fields as $key=>$label):?><div><dt><?=$label?></dt><dd><?=h($employee[$key]?:'Not entered')?></dd></div><?php endforeach;?></dl><?php if($employee['import_notes']):?><p class="hint"><?=h($employee['import_notes'])?></p><?php endif;?></section>
<?php if($tab==='employment'):?><section class="card"><h2>Account controls</h2><p class="hint">Deactivation immediately prevents sign-in. Archiving also removes the employee from the directory and retains their historical records.</p><div class="actions" style="margin-top:20px"><?php if(can($pdo,$user,'employees.edit')):?><form method="post" data-confirm="Change login access for this employee?"><?php ftoken();?><input type="hidden" name="action" value="toggle_employee"><input type="hidden" name="id" value="<?=$id?>"><button class="button"><?=$employee['active']?'Deactivate':'Activate'?> login</button></form><?php endif;if($user['role']==='super_admin'):?><form method="post" data-confirm="Archive this employee and disable their login? Historical records will be retained."><?php ftoken();?><input type="hidden" name="action" value="delete_employee"><input type="hidden" name="id" value="<?=$id?>"><button class="button danger">Archive employee</button></form><?php endif;?></div></section><?php if($user['role']==='super_admin'):?><section class="card"><h2>Reset employee password</h2><p class="hint">Use this when an employee cannot access their account. A password change is required at next sign-in and existing sessions are revoked.</p><form method="post" data-confirm="Reset this employee's password and sign out their existing sessions?"><?php ftoken();?><input type="hidden" name="action" value="reset_employee_password"><input type="hidden" name="id" value="<?=$id?>"><label>Temporary password<input type="password" name="temporary_password" minlength="12" maxlength="72" autocomplete="new-password"><span class="hint">Leave blank for User@123.</span></label><div class="form-actions"><button class="button">Reset password</button></div></form></section><?php endif;endif;
else:need($pdo,$user,'documents.view');$q=$pdo->prepare("SELECT r.*,(SELECT f.id FROM hr_files f WHERE f.record_id=r.id ORDER BY f.id DESC LIMIT 1) file_id FROM hr_records r WHERE r.module='documents' AND r.employee_id=? ORDER BY r.created_at DESC");$q->execute([$id]);$docs=$q->fetchAll(PDO::FETCH_ASSOC);$editDoc=(int)($_GET['document']??0);$doc=['data'=>'{}'];foreach($docs as $d)if((int)$d['id']===$editDoc)$doc=$d;$dv=array_merge(json_decode($doc['data'],true)?:[],$doc);if($error&&($_POST['action']??'')==='save_document')$dv=$_POST;
?><section class="card table-card"><div class="table-scroll"><table class="directory"><thead><tr><th>Document</th><th>Type</th><th>Issue date</th><th>Expiry</th><th>Actions</th></tr></thead><tbody><?php if(!$docs):?><tr><td colspan="5"><div class="empty-state">No documents uploaded yet.</div></td></tr><?php endif;foreach($docs as $d):$data=json_decode($d['data'],true)?:[];$expiry=$data['expires']??'';?><tr><td><?=h($d['title'])?></td><td><?=h($data['type']??'Other Documents')?></td><td><?=h($data['issued']??'—')?></td><td><?=h($expiry?:'—')?><?php if($expiry&&$expiry<=date('Y-m-d',strtotime('+30 days'))):?><p><?php fbadge($expiry<date('Y-m-d')?'Expired':'Expires soon',false);?></p><?php endif;?></td><td><div class="actions"><?php if($d['file_id']):?><a class="button small" href="document.php?id=<?=$d['file_id']?>">Download</a><?php endif;if(can($pdo,$user,'documents.edit')):?><a class="button small" href="?page=employee-view&id=<?=$id?>&tab=documents&document=<?=$d['id']?>">Edit</a><?php endif;if(can($pdo,$user,'documents.delete')):?><form method="post" data-confirm="Permanently delete this document and its uploaded versions?"><?php ftoken();?><input type="hidden" name="action" value="delete_document"><input type="hidden" name="document_id" value="<?=$d['id']?>"><button class="button small danger">Delete</button></form><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div></section>
<?php if(can($pdo,$user,$editDoc?'documents.edit':'documents.create')):?><section class="card"><div class="card-heading"><h2><?=$editDoc?'Edit':'Upload'?> document</h2></div><form method="post" enctype="multipart/form-data"><?php ftoken();?><input type="hidden" name="action" value="save_document"><input type="hidden" name="employee_id" value="<?=$id?>"><input type="hidden" name="document_id" value="<?=$editDoc?>"><div class="form-grid"><?php field('title','Document title',$dv,'text',true);choose('type','Document type',$dv,$docTypes);field('issued','Issue date',$dv,'date');field('expires','Expiry date',$dv,'date');?><label class="full">File (PDF, JPEG or PNG · up to 4 MB)<input type="file" name="document" accept="application/pdf,image/jpeg,image/png" <?=$editDoc?'':'required'?>></label><label class="full">Notes<textarea name="notes" maxlength="5000"><?=h($dv['notes']??'')?></textarea></label></div><div class="form-actions"><?php if($editDoc):?><a class="button" href="?page=employee-view&id=<?=$id?>&tab=documents">Cancel edit</a><?php endif;?><button class="button primary">Save document</button></div></form></section><?php endif;endif;?>

